import React, {useEffect, useRef, useState} from "react";
import {Alert, Autocomplete, Button, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, TextField} from "@mui/material";
import {Link, useNavigate, useParams, useSearchParams} from "react-router-dom";
import SaveOutlinedIcon from "@mui/icons-material/SaveOutlined";
import CalculateOutlinedIcon from "@mui/icons-material/CalculateOutlined";
import AddIcon from "@mui/icons-material/Add";
import {toast} from "react-toastify";
import {getApiErrorMessage} from "../../api/errors";
import useDebounce from "../../hooks/useDebounce";
import QueryError from "../shared/QueryError";
import Loader from "../../ui/loader/loader";
import {useAuth} from "../../auth/AuthContext";
import {useApproveCostMutation, useArchiveCostMutation, useCatalogCostQuery, useCloneCostMutation, useCostingCalculationQuery, useCostingCatalogQuery, useCostResourcesQuery, useCreateCostMutation, useLazyExportCostQuery, usePreviewCostMutation, useSaveCostMutation} from "./costingApi";
import {Calculation, CatalogItem, categories, CostInput, CostResult, emptyInput, money, newLine, newOverhead, statuses} from "./types";
import {LineFields, NumberField, OverheadFields} from "./CostFields";
import CostResults from "./CostResults";
import CostComparison from "./CostComparison";
import "./costing.css";

function Editor({id}: {id?: string}) {
    const navigate = useNavigate(); const [params] = useSearchParams(); const loadedId = useRef("");
    const [current, setCurrent] = useState<Calculation | null>(null);
    const [input, setInput] = useState<CostInput>(emptyInput);
    const [name, setName] = useState(""); const [notes, setNotes] = useState("");
    const [item, setItem] = useState<CatalogItem | null>(null); const [query, setQuery] = useState("");
    const [dirty, setDirty] = useState(false); const [result, setResult] = useState<CostResult | null>(null);
    const [resultStale, setResultStale] = useState(false); const [failure, setFailure] = useState("");
    const [confirm, setConfirm] = useState<"approve" | "archive" | null>(null);
    const [scenarioQuantity, setScenarioQuantity] = useState(10); const [scenario, setScenario] = useState<CostResult | null>(null);
    const initialId = Number(params.get("itemId")); const initialType = Number(params.get("itemType"));
    const {data: initialSummary} = useCatalogCostQuery({itemType: initialType, itemId: initialId}, {skip: !!id || initialId <= 0 || ![0, 1].includes(initialType)});
    const {data, isLoading, isError, error, refetch} = useCostingCalculationQuery(id ?? "", {skip: !id});
    const search = useDebounce(query); const {data: catalog = []} = useCostingCatalogQuery(search, {skip: !!id});
    const {data: resources = [], isError: resourcesError} = useCostResourcesQuery();
    const [create, createState] = useCreateCostMutation(); const [save, saveState] = useSaveCostMutation();
    const [preview, previewState] = usePreviewCostMutation(); const [approve, approveState] = useApproveCostMutation();
    const [archive, archiveState] = useArchiveCostMutation(); const [clone, cloneState] = useCloneCostMutation();
    const [exportCost] = useLazyExportCostQuery();
    const busy = createState.isLoading || saveState.isLoading || previewState.isLoading || approveState.isLoading || archiveState.isLoading || cloneState.isLoading;
    const readonly = current != null && current.status !== 0;
    const accept = (c: Calculation) => {setCurrent(c); setInput(c.snapshot.input); setName(c.name); setNotes(c.notes); setResult(c.snapshot.result); setItem({type: c.itemType, id: c.itemId, name: c.itemName, sellingPrice: c.snapshot.input.sellingPrice}); setDirty(false); setResultStale(false); setFailure("");};
    useEffect(() => {if (data && loadedId.current !== data.id) {loadedId.current = data.id; accept(data);}}, [data]);
    useEffect(() => {if (initialSummary && !loadedId.current) {loadedId.current = "initial"; setItem(initialSummary.item); setName(`Калькуляция · ${initialSummary.item.name}`); setInput(prev => ({...prev, sellingPrice: initialSummary.item.sellingPrice}));}}, [initialSummary]);
    useEffect(() => {
        const handler = (event: BeforeUnloadEvent) => {if (dirty) {event.preventDefault(); event.returnValue = "";}};
        window.addEventListener("beforeunload", handler); return () => window.removeEventListener("beforeunload", handler);
    }, [dirty]);
    const change = (next: CostInput) => {setInput(next); setDirty(true); setResultStale(true); setScenario(null);};
    const set = (key: keyof CostInput, value: number | string | boolean) => change({...input, [key]: value});
    const run = async (action: () => Promise<void>) => {setFailure(""); try {await action();} catch (e) {setFailure(getApiErrorMessage(e, "Не удалось выполнить действие."));}};
    const saveDraft = () => run(async () => {
        if (!item || !name.trim()) throw new Error("Выберите позицию каталога и укажите название.");
        const c = current ? await save({id: current.id, name, notes, input, stamp: current.stamp}).unwrap()
            : await create({itemType: item.type, itemId: item.id, name, notes, input, kind: 0, baselineId: null}).unwrap();
        accept(c); toast.success("Калькуляция сохранена"); if (!id) navigate(`/costing/${c.id}`, {replace: true});
    });
    const calculate = () => run(async () => {if (!item) throw new Error("Выберите товар или услугу."); setResult(await preview({itemType: item.type, itemId: item.id, input}).unwrap()); setResultStale(false);});
    const duplicate = (kind: number) => run(async () => {if (current) {const c = await clone({id: current.id, kind}).unwrap(); navigate(`/costing/${c.id}`);}});
    const confirmAction = () => run(async () => {if (!current) return; const c = confirm === "approve" ? await approve({id: current.id, stamp: current.stamp}).unwrap() : await archive({id: current.id, stamp: current.stamp}).unwrap(); accept(c); setConfirm(null);});
    const download = () => run(async () => {if (!current) return; const blob = await exportCost(current.id).unwrap(); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `costing-${current.itemId}-v${current.version}.csv`; a.click(); URL.revokeObjectURL(url);});
    if (isLoading) return <Loader/>;
    if (isError) return <div className="cost-page"><QueryError error={error} onRetry={refetch}/></div>;
    return <div className="cost-page">
        <header className="cost-header"><div><span className="cost-eyebrow">Себестоимость / {current?.kind === 1 ? "Фактический расчёт" : "Нормативный расчёт"}</span><h1>{current ? `Калькуляция · версия ${current.version}` : "Новая калькуляция"}</h1><p>{item?.name || "Выберите товар или услугу, добавьте ресурсы и задайте правила распределения."}</p></div><div className="cost-actions"><Button component={Link} to="/costing">Реестр</Button>{current && <Chip label={statuses[current.status]} color={current.status === 1 ? "success" : "default"}/>}</div></header>
        {failure && <Alert severity="error" action={id ? <Button onClick={() => {loadedId.current = ""; void refetch();}}>Обновить</Button> : undefined}>{failure}</Alert>}
        {dirty && <Alert severity="info">Есть несохранённые изменения. Сохраните их перед утверждением, экспортом или созданием версии.</Alert>}
        {readonly && <Alert severity="success">Ставки и результат этой версии зафиксированы. Для изменений создайте новую версию.</Alert>}
        <div className="cost-actions">
            {!readonly && <><Button variant="contained" startIcon={<SaveOutlinedIcon/>} disabled={busy} onClick={() => void saveDraft()}>Сохранить черновик</Button><Button variant="outlined" startIcon={<CalculateOutlinedIcon/>} disabled={busy || !item} onClick={() => void calculate()}>Рассчитать</Button></>}
            {current && <><Button disabled={busy || dirty} onClick={() => void duplicate(0)}>Новая версия</Button>{current.kind === 0 && current.approvedAt && <Button disabled={busy || dirty} onClick={() => void duplicate(1)}>Создать факт по плану</Button>}<Button disabled={busy || dirty} onClick={() => void download()}>Экспорт CSV</Button><Button disabled={busy || dirty} onClick={() => window.print()}>Печать</Button></>}
            {current?.status === 0 && <Button color="success" variant="outlined" disabled={busy || dirty} onClick={() => setConfirm("approve")}>Утвердить</Button>}
            {current && current.status !== 3 && <Button color="warning" disabled={busy || dirty} onClick={() => setConfirm("archive")}>В архив</Button>}
        </div>
        <div className="cost-grid"><div className="cost-main">
            <section className="cost-panel"><h2>Позиция и параметры выпуска</h2><div className="cost-fields">
                {!id && <Autocomplete options={catalog} value={item} isOptionEqualToValue={(a, b) => a.type === b.type && a.id === b.id} getOptionLabel={x => `${x.type === 0 ? "Товар" : "Услуга"} · ${x.name}`} onInputChange={(_, v, reason) => {if (reason === "input") setQuery(v);}} onChange={(_, v) => {setItem(v); if (v) {setName(`Калькуляция · ${v.name}`); change({...input, sellingPrice: v.sellingPrice});}}} renderInput={p => <TextField {...p} size="small" label="Товар или услуга"/>}/>}
                <TextField size="small" label="Название калькуляции" value={name} disabled={readonly} onChange={e => {setName(e.target.value); setDirty(true);}}/>
                <TextField size="small" label="Валюта затрат" value={input.currency} disabled={readonly} inputProps={{maxLength: 3}} onChange={e => set("currency", e.target.value.toUpperCase())}/>
                <NumberField label="Выпуск партии / объём услуги" value={input.outputQuantity} disabled={readonly} onChange={v => set("outputQuantity", v)}/>
                <NumberField label="Потери готового выпуска, %" value={input.outputLossPercent} max={99.99} disabled={readonly} onChange={v => set("outputLossPercent", v)}/>
                <NumberField label="Человеко-часы на единицу" value={input.laborHoursPerUnit} disabled={readonly} onChange={v => set("laborHoursPerUnit", v)}/>
                <NumberField label="Машино-часы на единицу" value={input.machineHoursPerUnit} disabled={readonly} onChange={v => set("machineHoursPerUnit", v)}/>
                <NumberField label="Цена продажи в валюте расчёта" value={input.sellingPrice} disabled={readonly} onChange={v => set("sellingPrice", v)}/>
                <NumberField label="Налог продажи, %" value={input.salesTaxPercent} max={100} disabled={readonly} onChange={v => set("salesTaxPercent", v)}/>
                <NumberField label="Целевая маржа, %" value={input.targetMarginPercent} max={99.99} disabled={readonly} onChange={v => set("targetMarginPercent", v)}/>
                <FormControlLabel label="Цена продажи включает налог" control={<Checkbox checked={input.sellingPriceIncludesTax} disabled={readonly} onChange={e => set("sellingPriceIncludesTax", e.target.checked)}/>}/>
            </div><TextField sx={{mt: 2}} size="small" fullWidth multiline minRows={2} label="Основания, допущения, документы" value={notes} disabled={readonly} onChange={e => {setNotes(e.target.value); setDirty(true);}}/></section>
            <section className="cost-panel"><div className="cost-header"><h2>Ресурсы и статьи затрат</h2>{!readonly && <Button startIcon={<AddIcon/>} onClick={() => change({...input, lines: [...input.lines, newLine()]})}>Добавить статью</Button>}</div>
                {resourcesError && <Alert severity="warning">Справочник ресурсов не загружен. Можно вводить ставки вручную.</Alert>}
                {!input.lines.length && <div className="cost-empty"><strong>Соберите структуру затрат</strong><span>Материалы, труд, оборудование, подрядчики и доставка.</span>{!readonly && <div className="cost-actions">{[0, 1, 2, 3].map(c => <Button key={c} onClick={() => change({...input, lines: [...input.lines, newLine(c)]})}>+ {categories[c]}</Button>)}</div>}</div>}
                {input.lines.map((line, i) => <LineFields key={line.id} line={line} index={i} resources={resources} disabled={readonly} onChange={next => change({...input, lines: input.lines.map(l => l.id === next.id ? next : l)})} onRemove={() => change({...input, lines: input.lines.filter(l => l.id !== line.id)})}/>)}
            </section>
            <section className="cost-panel"><div className="cost-header"><h2>Распределение накладных расходов</h2>{!readonly && <Button startIcon={<AddIcon/>} onClick={() => change({...input, overheads: [...input.overheads, newOverhead()]})}>Добавить правило</Button>}</div>
                {!input.overheads.length && <p>Распределяйте расходы по выпуску, часам, стоимости материалов, труду или операциям ABC.</p>}
                {input.overheads.map((rule, i) => <OverheadFields key={rule.id} rule={rule} index={i} disabled={readonly} onChange={next => change({...input, overheads: input.overheads.map(l => l.id === next.id ? next : l)})} onRemove={() => change({...input, overheads: input.overheads.filter(l => l.id !== rule.id)})}/>)}
            </section>
            {result && <section className="cost-panel"><h2>Расшифровка расчёта</h2><div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Статья</th><th>Количество / база</th><th>Ставка</th><th>Сумма</th></tr></thead><tbody>{result.breakdown.map(l => <tr key={l.id}><td>{l.name}<small>{categories[l.category]} · {l.formula}</small></td><td className="number">{money(l.quantity, 4)}</td><td className="number">{money(l.rate, 4)}</td><td className="number">{money(l.total)}</td></tr>)}</tbody></table></div></section>}
            {current?.kind === 1 && current.baselineId && <CostComparison plannedId={current.baselineId} actualId={current.id}/>}
            {current && <section className="cost-panel"><h2>История действий</h2><table className="cost-table"><tbody>{current.events.slice().reverse().map((e, i) => <tr key={i}><td>{new Date(e.at).toLocaleString("ru-RU")}</td><td>{e.actor}</td><td>{e.note}</td></tr>)}</tbody></table></section>}
        </div><aside className="cost-aside">
            {resultStale && <Alert severity="warning">Параметры изменились. Нажмите «Рассчитать», чтобы обновить показатели.</Alert>}
            {result ? <CostResults result={result}/> : <section className="cost-panel"><h2>Результат</h2><p>Добавьте затраты и нажмите «Рассчитать». Показатели рассчитываются на сервере.</p></section>}
            {!readonly && <section className="cost-panel"><h2>Сценарий объёма</h2><NumberField label="Другой объём партии" value={scenarioQuantity} onChange={setScenarioQuantity}/><Button sx={{mt: 1}} disabled={!item || busy} onClick={() => void run(async () => {if (item) setScenario(await preview({itemType: item.type, itemId: item.id, input: {...input, outputQuantity: scenarioQuantity}}).unwrap());})}>Проверить сценарий</Button>{scenario && <p>Полная себестоимость: <strong>{money(scenario.fullUnitCost)} {scenario.currency}/ед.</strong><br/>Прибыль: {money(scenario.profitPerUnit)}/ед.</p>}<p className="cost-note">Разовые затраты партии сохраняются. Общие мощности пула остаются заданными; при необходимости скорректируйте их.</p></section>}
            {item && <Button component={Link} to={item.type === 0 ? `/productDetails/${item.id}` : `/servicesManagement/${item.id}`}>Открыть карточку {item.type === 0 ? "товара" : "услуги"}</Button>}
        </aside></div>
        <Dialog open={!!confirm} onClose={() => {if (!busy) setConfirm(null);}}><DialogTitle>{confirm === "approve" ? "Утвердить калькуляцию?" : "Перенести в архив?"}</DialogTitle><DialogContent>{confirm === "approve" ? current?.kind === 0 ? "Эта версия станет действующей в карточке каталога. Предыдущая версия сохранится в истории. Цена продажи в каталоге не меняется." : "Фактические затраты будут зафиксированы для сравнения с планом." : "Если версия действует в каталоге, карточка останется без утверждённой себестоимости до утверждения другой версии."}</DialogContent><DialogActions><Button disabled={busy} onClick={() => setConfirm(null)}>Отмена</Button><Button disabled={busy} onClick={() => void confirmAction()}>Подтвердить</Button></DialogActions></Dialog>
    </div>;
}
export default function CostingEditor() {const {id} = useParams<{id: string}>(); const {isCompanyAdmin, isSuperAdmin} = useAuth(); return isCompanyAdmin || isSuperAdmin ? <Editor key={id || "new"} id={id}/> : <div className="cost-page"><Alert severity="info">Расчёты себестоимости доступны администратору компании.</Alert></div>;}
