import React from "react";
import {Alert} from "@mui/material";
import {categories, CostResult, money} from "./types";

export default function CostResults({result}: {result: CostResult}) {
    return <>
        <div className="cost-stats">
            <div className="cost-stat"><span>Производственная / ед.</span><strong>{money(result.productionUnitCost)}</strong><small>{result.currency}</small></div>
            <div className="cost-stat"><span>Полная / ед.</span><strong>{money(result.fullUnitCost)}</strong><small>{result.currency}</small></div>
            <div className={`cost-stat ${result.profitPerUnit < 0 ? "negative" : ""}`}><span>Прибыль / ед.</span><strong>{money(result.profitPerUnit)}</strong><small>Без налога продажи</small></div>
            <div className="cost-stat"><span>Маржа / наценка</span><strong>{money(result.marginPercent)}%</strong><small>Наценка {money(result.markupPercent)}%</small></div>
        </div>
        <section className="cost-panel"><h2>Цена и выпуск</h2><table className="cost-table"><tbody>
            {[["Рекомендуемая цена без налога", money(result.suggestedNetPrice)], ["Рекомендуемая цена с налогом", money(result.suggestedGrossPrice)], ["Годный выпуск", money(result.goodOutputQuantity, 4)], ["Полные затраты партии", money(result.fullCost)], ["Переменные / единицу", money(result.variableUnitCost)], ["Постоянные затраты партии", money(result.fixedCost)], ["Точка безубыточности, ед.", money(result.breakEvenQuantity, 4)], ["Возмещаемый НДС", money(result.recoverableTax)], ["Недозагрузка пула · расход периода", money(result.unallocatedOverhead)]].map(([label, value]) => <tr key={label}><td>{label}</td><td className="number">{value}</td></tr>)}
        </tbody></table><p className="cost-note">Точка безубыточности рассчитана для постоянных затрат этой партии при неизменных ставках и структуре затрат. Недозагрузка относится ко всему пулу и не прибавляется к себестоимости.</p></section>
        <section className="cost-panel"><h2>Структура затрат</h2>{result.categories.map(x => <div key={x.category}><div className="cost-header"><span>{categories[x.category]}</span><strong>{money(x.sharePercent)}%</strong></div><div className="cost-bar"><span style={{width: `${x.sharePercent}%`}}/></div></div>)}</section>
        {result.warnings.map(w => <Alert key={w} severity="warning">{w}</Alert>)}
    </>;
}
