import React from "react";
import {Alert} from "@mui/material";
import {useCostComparisonQuery} from "./costingApi";
import {money} from "./types";
import QueryError from "../shared/QueryError";

export default function CostComparison({plannedId, actualId}: {plannedId: string; actualId: string}) {
    const {data, isLoading, isError, error, refetch} = useCostComparisonQuery({plannedId, actualId});
    if (isLoading) return <p>Загрузка план-факта…</p>;
    if (isError) return <QueryError error={error} onRetry={refetch}/>;
    if (!data) return null;
    return <section className="cost-panel"><h2>План-факт · на единицу годного выпуска</h2><Alert severity={data.unitVariance > 0 ? "warning" : "success"}>План {money(data.plannedUnitCost, 4)} → факт {money(data.actualUnitCost, 4)} {data.currency}. Отклонение {money(data.unitVariance, 4)} ({money(data.unitVariancePercent)}%).</Alert>
        <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Статья</th><th>План / ед.</th><th>Факт / ед.</th><th>Отклонение</th><th>%</th></tr></thead><tbody>{data.lines.map(l => <tr key={l.lineId}><td>{l.name}</td><td className="number">{money(l.planned, 4)}</td><td className="number">{money(l.actual, 4)}</td><td className="number">{money(l.variance, 4)}</td><td className="number">{money(l.percent)}</td></tr>)}</tbody></table></div>
    </section>;
}
